"""Plain text absence notices for parents."""

from rosterkit.models import Student
from rosterkit.attendance import days_missed


def check_owner(student, marks):
    """Refuse marks that belong to someone else."""
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id!r} given with "
                f"student {student.student_id!r}"
            )


def long_date(day):
    return f"{day:%B} {day.day}, {day.year}"


def compose(student, days):
    count = len(days)
    unit = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    lines = [f"{name} was absent for {count} {unit}:"]
    lines.extend(f"- {long_date(day)}" for day in days)
    return "\n".join(lines)


# ---
def build_absence_notice(student: Student, marks) -> str:
    """Notice with student, day count and dates."""
    own = list(marks)
    check_owner(student, own)
    days = sorted(set(days_missed(own)))
    if not days:
        raise ValueError("no absences to report")
    return compose(student, days)

