import unittest
from rosterkit.notices import build_absence_notice
from rosterkit.models import Mark, Student
from datetime import date

PUPIL = Student("7", "Rivera", "Ana", "A")

# ---
def mark(day, status="absent", pupil_id="7"):
    return Mark(pupil_id, day, status)

class NoticeTests(unittest.TestCase):
    def test_dates_in_order(self):
        marks = [
            mark(date(2026, 9, 10)),
            mark(date(2026, 9, 3)),
            mark(date(2026, 9, 4), "present")
        ]
        text = build_absence_notice(PUPIL, marks)
        self.assertEqual(
            text,
            "Ana Rivera was absent for 2 days:\n"
            "- September 3, 2026\n"
            "- September 10, 2026"
        )

    def test_single_day(self):
        text = build_absence_notice(
            PUPIL, [mark(date(2026, 9, 3))]
        )
        self.assertIn("for 1 day:", text)

    def test_excused_not_listed(self):
        marks = [
            mark(date(2026, 9, 3)),
            mark(date(2026, 9, 4), "excused")
        ]
        text = build_absence_notice(PUPIL, marks)
        self.assertNotIn("September 4", text)

    def test_repeated_day_counts_once(self):
        day = date(2026, 9, 3)
        text = build_absence_notice(
            PUPIL, [mark(day), mark(day)]
        )
        self.assertIn("for 1 day:", text)

    def test_other_student(self):
        marks = [
            mark(date(2026, 9, 3)),
            mark(date(2026, 9, 4), pupil_id="8")
        ]
        with self.assertRaises(ValueError):
            build_absence_notice(PUPIL, marks)

    def test_no_absences(self):
        marks = [mark(date(2026, 9, 3), "late")]
        with self.assertRaises(ValueError):
            build_absence_notice(PUPIL, marks)

    def test_no_marks(self):
        with self.assertRaises(ValueError):
            build_absence_notice(PUPIL, [])

if __name__ == "__main__":
    unittest.main()
